INSERT INTO public.dataset_sources (source_id, name, license, license_url, provenance_summary, is_released_practice_set, is_official_college_board, record_count) VALUES ('hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'https://creativecommons.org/licenses/by/4.0/', 'HDSAT original practice items drafted for HDSAT against the publicly published SAT Suite domain/skill blueprint (collegeboard.org). AI-assisted drafting with a human review checklist (see supabase/import/REVIEW_CHECKLIST.md). NOT official College Board material and NOT derived from any College Board test form.', FALSE, FALSE, 29) ON CONFLICT (source_id) DO UPDATE SET name = EXCLUDED.name, license = EXCLUDED.license, license_url = EXCLUDED.license_url, provenance_summary = EXCLUDED.provenance_summary, is_released_practice_set = EXCLUDED.is_released_practice_set, record_count = EXCLUDED.record_count;
INSERT INTO public.dataset_sources (source_id, name, license, license_url, provenance_summary, is_released_practice_set, is_official_college_board, record_count) VALUES ('hdsat-benchmark-sim-1', 'HDSAT Benchmark Simulation Set A (Released Practice Form)', 'CC-BY-4.0', 'https://creativecommons.org/licenses/by/4.0/', 'HDSAT original practice items reserved for the HDSAT Benchmark Form A simulation. Deliberately tagged is_released_practice_set=true so students can exclude benchmark-simulation items while drilling in the Question Bank or Practice Rush. NOT official College Board material.', TRUE, FALSE, 7) ON CONFLICT (source_id) DO UPDATE SET name = EXCLUDED.name, license = EXCLUDED.license, license_url = EXCLUDED.license_url, provenance_summary = EXCLUDED.provenance_summary, is_released_practice_set = EXCLUDED.is_released_practice_set, record_count = EXCLUDED.record_count;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-001', 'HDSAT-RW-INF-001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Marine biologist Adriana Vergés and her colleagues have documented how warming ocean temperatures allow tropical herbivorous fish to expand their ranges into temperate kelp forests. Unlike native temperate species, these tropical browsers consume kelp blades at rates that exceed the algae''s seasonal regrowth capacity, gradually transforming dense canopy habitats into sparse rocky reefs.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Range expansion by tropical herbivorous fish into warming temperate waters can deplete kelp forests faster than the kelp can regenerate."}, {"id": "B", "text": "Ocean warming affects rocky reefs more severely than it affects shallow coastal waters."}, {"id": "C", "text": "Temperate kelp forests grow more rapidly during warm seasons than tropical coral reefs do."}, {"id": "D", "text": "Native temperate fish species have adapted their diets to compete with arriving tropical browsers."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-002', 'HDSAT-RW-INF-002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'In medieval European scriptoria, parchment made from calfskin (vellum) was prized for illuminated manuscripts because its smooth, low-lipid surface accepted gold leaf and mineral pigments evenly. However, archival multispectral imaging of twelfth-century parish registries—documents intended for routine administrative tracking rather than liturgical display—shows that scribes overwhelmingly selected coarser sheepskin parchment, which split easily if scraped to remove ink.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Because parish registries did not require decorative illumination, scribes prioritized sheepskin''s resistance to undetected erasure and lower cost over vellum''s smooth finish."}, {"id": "B", "text": "Multispectral imaging cannot distinguish between calfskin and sheepskin in illuminated liturgical manuscripts."}, {"id": "C", "text": "Twelfth-century scribes lacked access to mineral pigments when compiling administrative parish registries."}, {"id": "D", "text": "Vellum manuscripts deteriorated more rapidly in parish archives than sheepskin registries did."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-003', 'HDSAT-RW-INF-003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'Agronomists tested four cover-crop mixtures across 120 days to evaluate soil nitrogen retention and late-season weed suppression in upper Midwest plots.
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-004', 'HDSAT-RW-INF-004', ARRAY['SAT', 'PSAT/NMSQT']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Hard', 'multiple_choice', 'Literary critic Priya Nair argues that in nineteenth-century industrial novels, depictions of railway schedules do not merely provide realistic background detail; rather, they dramatize how standardized mechanical time reshaped characters'' intimate perception of memory and obligation.', 'Which quotation from a nineteenth-century novel would most directly illustrate Nair''s claim?', '[{"id": "A", "text": "\"Passengers waiting on the windy platform consulted the printed timetable nailed beside the ticket window before stowing their trunks.\""}, {"id": "B", "text": "\"The new viaduct spanned forty arches of dressed limestone, carrying the morning express high above the canal barges that had served the valley for a century.\""}, {"id": "C", "text": "\"Because the locomotive required fresh water every thirty miles, the company constructed iron tanks at each market town along the route.\""}, {"id": "D", "text": "\"Even in the quiet parlor of his childhood home, Julian found himself measuring his father''s pauses by the six-minute intervals of the junction bell, as though affection itself were a connection to be missed.\""}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-005', 'HDSAT-RW-INF-005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Unlike traditional concrete, which releases carbon dioxide during limestone calcination, mycelium-based acoustic panels are grown by binding agricultural agricultural byproducts—such as hemp hurds or oat hulls—with the root-like fungal network of Ganoderma lucidum. Once heat-cured, the panels are fire-retardant, biodegradable, and absorb midrange office noise more effectively than fiberglass tiles.', 'According to the text, how are mycelium-based acoustic panels produced?', '[{"id": "A", "text": "By heating limestone with fiberglass tiles to reduce midrange office noise."}, {"id": "B", "text": "By extracting carbon dioxide from traditional concrete during calcination."}, {"id": "C", "text": "By compressing synthetic polymers around live hemp plants."}, {"id": "D", "text": "By using fungal networks to bind agricultural plant byproducts and then heat-curing the material."}]'::jsonb, NULL, 'hdsat-benchmark-sim-1', 'HDSAT Benchmark Simulation Set A (Released Practice Form)', 'CC-BY-4.0', 'HDSAT Benchmark Simulation Set A (Released Practice Form) (CC-BY-4.0)', TRUE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-006', 'HDSAT-RW-INF-006', ARRAY['SAT', 'PSAT/NMSQT']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Paleoclimatologists reconstructing monsoon intensity from stalagmite oxygen-isotope ratios ($\delta^{18}\text{O}$) long assumed that lower $\delta^{18}\text{O}$ values in cave calcite strictly reflect higher local rainfall volume. Recently, however, atmospheric tracer models demonstrated that shifts in the geographic moisture source—from the Arabian Sea to the Bay of Bengal—can lower precipitation $\delta^{18}\text{O}$ by up to 3 per mil even when total local rainfall remains constant.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Oxygen-isotope ratios in cave calcite remain constant regardless of changes in regional monsoon circulation."}, {"id": "B", "text": "Stalagmites formed near the Arabian Sea grow more rapidly than those formed near the Bay of Bengal."}, {"id": "C", "text": "Atmospheric tracer models are less reliable than stalagmite calcite measurements for dating ancient cave formations."}, {"id": "D", "text": "Interpreting stalagmite $\\delta^{18}\\text{O}$ records as a direct measure of local rainfall volume may be inaccurate if concurrent changes in moisture-source pathways are not accounted for."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-001', 'HDSAT-RW-CRF-001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'Whereas early portable seismographs required delicate mechanical pendulums that could be disrupted by minor jostling during transport, modern solid-state accelerometers are remarkably _______, functioning reliably even when dropped from reconnaissance aircraft into volcanic craters.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "tentative"}, {"id": "B", "text": "resilient"}, {"id": "C", "text": "ambiguous"}, {"id": "D", "text": "ephemeral"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-002', 'HDSAT-RW-CRF-002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'Architect Lina Bo Bardi rejected the notion that museum display cases should isolate artworks from everyday life; instead, at the São Paulo Museum of Art, she mounted paintings on transparent tempered-glass easels so visitors could move freely among the works in a _______ spatial arrangement.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "perfunctory"}, {"id": "B", "text": "clandestine"}, {"id": "C", "text": "nonhierarchical"}, {"id": "D", "text": "redundant"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-003', 'HDSAT-RW-CRF-003', ARRAY['SAT', 'PSAT/NMSQT']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Hard', 'multiple_choice', 'Far from offering a _______ endorsement of algorithmic credit scoring, economist Safiya Patel demonstrates that while automated underwriting reduces processing delays for standard mortgages, it systematically amplifies historical data gaps for first-generation rural borrowers.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "mendacious"}, {"id": "B", "text": "parsimonious"}, {"id": "C", "text": "derivative"}, {"id": "D", "text": "univocal"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-004', 'HDSAT-RW-CRF-004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Many popular accounts of the 1925 serum run to Nome credit a single lead sled dog, Balto, with saving the isolated Alaskan town from a diphtheria outbreak. Historian Gay Salisbury and Laney Salisbury, however, emphasize that the 674-mile relay involved twenty mushers and roughly 150 dogs, with Leonhard Seppala''s team—led by Togo—covering the longest and most hazardous crossing over Norton Sound.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It chronicles the chronological stages of a medical emergency and then proposes a policy to prevent future outbreaks."}, {"id": "B", "text": "It compares two competing scientific explanations for a phenomenon and argues that neither is complete."}, {"id": "C", "text": "It presents a widely held simplified view of a historical event and then offers historical details that complicate that view."}, {"id": "D", "text": "It praises an individual achievement and then explains why contemporary observers ignored it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
