INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-SEC-001', 'HDSAT-RW-SEC-001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'In 1899, physicist Hertha Ayrton read her paper on the behavior of electric arcs before the Institution of Electrical Engineers in _______ she became the first woman invited to become a full member of the prestigious society.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": "London, shortly thereafter"}, {"id": "B", "text": "London; shortly thereafter,"}, {"id": "C", "text": "London, shortly thereafter,"}, {"id": "D", "text": "London shortly thereafter"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-SEC-002', 'HDSAT-RW-SEC-002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Form, Structure, and Sense', 'Medium', 'multiple_choice', 'The acoustics of ancient Greek amphitheaters—most notably Epidaurus, whose limestone seating tiers filter out low-frequency background wind noise while amplifying high-frequency vocal consonants—_______ modern architectural engineers for decades.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": "have intrigued"}, {"id": "B", "text": "intrigues"}, {"id": "C", "text": "has intrigued"}, {"id": "D", "text": "is intriguing"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-SEC-003', 'HDSAT-RW-SEC-003', ARRAY['SAT', 'PSAT/NMSQT']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Form, Structure, and Sense', 'Hard', 'multiple_choice', 'Calibrated using laser interferometry in an underground vacuum chamber, _______ can detect gravitational-wave strain amplitudes smaller than one ten-thousandth the diameter of a proton.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": "gravitational-wave strain amplitudes at the LIGO observatory"}, {"id": "B", "text": "physicists'' measurements of the LIGO observatory''s silica mirrors"}, {"id": "C", "text": "it is the LIGO observatory''s suspended silica mirrors that"}, {"id": "D", "text": "the suspended silica mirrors of the LIGO observatory"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-SEC-004', 'HDSAT-RW-SEC-004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'Botanist Robin Wall Kimmerer observes that when sweetgrass (Hierochloe odorata) is harvested selectively by _______ the plant responds with vigorous compensatory tillering, producing denser shoots the following spring than unharvested plots do.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": "hand"}, {"id": "B", "text": "hand;"}, {"id": "C", "text": "hand,"}, {"id": "D", "text": "hand—"}]'::jsonb, NULL, 'hdsat-benchmark-sim-1', 'HDSAT Benchmark Simulation Set A (Released Practice Form)', 'CC-BY-4.0', 'HDSAT Benchmark Simulation Set A (Released Practice Form) (CC-BY-4.0)', TRUE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-EXP-001', 'HDSAT-RW-EXP-001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'Early twentieth-century glacialogists assumed that subglacial lakes beneath the Antarctic ice sheet were hydrologically isolated basins that remained stagnant for millions of years. _______ satellite laser altimetry in the 2000s revealed rapid rises and falls in the ice surface above Lake Whillans, proving that subglacial water periodically flushes through interconnected channels.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "However,"}, {"id": "B", "text": "Similarly,"}, {"id": "C", "text": "Consequently,"}, {"id": "D", "text": "For instance,"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
