INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-ALG-001', 'HDSAT-M-ALG-001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Algebra', 'Linear equations in one variable', 'Easy', 'multiple_choice', 'A botanical conservatory maintains a tropical orchid room by running a misting system. The reservoir starts the day with $480$ liters of distilled water and releases $15$ liters per hour. If $W$ represents the volume of water remaining after $t$ hours, and $W = 480 - 15t$, after how many hours will exactly $195$ liters remain?', 'What is the value of $t$ when $W = 195$?', '[{"id": "A", "text": "$32$"}, {"id": "B", "text": "$19$"}, {"id": "C", "text": "$17$"}, {"id": "D", "text": "$21$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
