INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-ALG-003', 'HDSAT-M-ALG-003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Algebra', 'Linear functions', 'Easy', 'multiple_choice', 'A municipal bike-share program charges a monthly membership fee plus a constant usage rate per minute for rides exceeding $30$ minutes. The function $C(m) = 18 + 0.15m$ gives the total monthly cost $C(m)$, in dollars, for a member who accumulates $m$ overage minutes during the month.', 'What is the best interpretation of the number $18$ in this context?', '[{"id": "A", "text": "The total cost, in dollars, of an $18$-minute bike ride."}, {"id": "B", "text": "The charge, in dollars, for each additional minute beyond $30$ minutes."}, {"id": "C", "text": "The fixed monthly membership fee, in dollars, when a member has $0$ overage minutes."}, {"id": "D", "text": "The maximum number of overage minutes included in the base plan."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-ALG-004', 'HDSAT-M-ALG-004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Algebra', 'Linear inequalities in one or two variables', 'Medium', 'multiple_choice', 'A bakery produces loaves of sourdough bread that each require $0.6$ kilograms of flour and batches of brioche rolls that each require $0.4$ kilograms of flour. The bakery has at most $36$ kilograms of flour available for the morning bake and must prepare at least $30$ loaves of sourdough bread to fulfill standing restaurant orders.', 'If $s$ represents the number of sourdough loaves and $b$ represents the number of brioche batches, what is the maximum number of brioche batches the bakery can produce?', '[{"id": "A", "text": "$90$"}, {"id": "B", "text": "$45$"}, {"id": "C", "text": "$30$"}, {"id": "D", "text": "$60$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
