INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-ADV-001', 'HDSAT-M-ADV-001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Advanced Math', 'Equivalent expressions', 'Easy', 'multiple_choice', '$$(2x^2 - 5x + 3) - (x^2 - 4x - 7)$$', 'Which of the following is equivalent to the given expression?', '[{"id": "A", "text": "$x^2 - 9x - 4$"}, {"id": "B", "text": "$x^2 - x - 4$"}, {"id": "C", "text": "$x^2 - x + 10$"}, {"id": "D", "text": "$3x^2 - 9x + 10$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-ADV-002', 'HDSAT-M-ADV-002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Math', 'Advanced Math', 'Nonlinear functions', 'Medium', 'multiple_choice', 'The height $h(t)$, in meters above the ground, of a weather probe launched vertically from a platform is modeled by the function $h(t) = -5t^2 + 40t + 12$, where $t$ is the time in seconds after launch.', 'What is the maximum height, in meters, reached by the probe?', '[{"id": "A", "text": "$52$"}, {"id": "B", "text": "$92$"}, {"id": "C", "text": "$4$"}, {"id": "D", "text": "$80$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-ADV-003', 'HDSAT-M-ADV-003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Math', 'Advanced Math', 'Nonlinear equations in one variable and systems of equations in two variables', 'Medium', 'spr', '$$x^2 - 11x + 24 = 0$$', 'What is the positive difference between the two solutions to the given quadratic equation?', NULL, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-ADV-004', 'HDSAT-M-ADV-004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Math', 'Advanced Math', 'Nonlinear functions', 'Hard', 'multiple_choice', 'A culture of bioluminescent bacteria initially contains $2{,}500$ cells. Under controlled nutrient conditions, the population doubles every $3$ hours.', 'Which function $P(t)$ best models the number of bacteria in the culture $t$ hours after the start of the observation?', '[{"id": "A", "text": "$P(t) = 2{,}500(3)^{t/2}$"}, {"id": "B", "text": "$P(t) = 2{,}500(2)^{t/3}$"}, {"id": "C", "text": "$P(t) = 2{,}500 + 2^{t/3}$"}, {"id": "D", "text": "$P(t) = 2{,}500(2)^{3t}$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-ADV-005', 'HDSAT-M-ADV-005', ARRAY['SAT', 'PSAT/NMSQT']::TEXT[], 'Math', 'Advanced Math', 'Nonlinear equations in one variable and systems of equations in two variables', 'Hard', 'spr', '$$2x^2 - 12x + c = 0$$', 'In the given equation, $c$ is a constant. If the equation has exactly one real solution, what is the value of $c$?', NULL, NULL, 'hdsat-benchmark-sim-1', 'HDSAT Benchmark Simulation Set A (Released Practice Form)', 'CC-BY-4.0', 'HDSAT Benchmark Simulation Set A (Released Practice Form) (CC-BY-4.0)', TRUE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-PSD-001', 'HDSAT-M-PSD-001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Problem-Solving and Data Analysis', 'Percentages', 'Easy', 'multiple_choice', 'During an annual clearance sale, a scientific instrument supplier reduces the price of a digital oscilloscope by $20\%$. A university laboratory also applies an educational grant discount that takes an additional $10\%$ off the sale price.', 'If the original list price of the oscilloscope was $\$650$, what is the final price paid by the laboratory, before tax?', '[{"id": "A", "text": "$\\$468$"}, {"id": "B", "text": "$\\$520$"}, {"id": "C", "text": "$\\$585$"}, {"id": "D", "text": "$\\$455$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-PSD-002', 'HDSAT-M-PSD-002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Problem-Solving and Data Analysis', 'One-variable data: distributions and measures of center and spread', 'Medium', 'spr', 'The table shows the daily particulate matter readings (in micrograms per cubic meter) recorded at an air-quality station over $6$ days: $14, 18, 21, 21, 25, 33$. On the seventh day, a reading of $92$ micrograms per cubic meter is recorded due to a regional dust event.', 'By how much does the mean of the $7$-day dataset exceed the median of the $7$-day dataset?', NULL, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-PSD-003', 'HDSAT-M-PSD-003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Problem-Solving and Data Analysis', 'Probability and conditional probability', 'Medium', 'multiple_choice', 'A quality-control engineer inspected $240$ solar panels from two production lines.
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-PSD-004', 'HDSAT-M-PSD-004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Math', 'Problem-Solving and Data Analysis', 'Inference from sample statistics and margin of error', 'Hard', 'multiple_choice', 'A transit authority surveyed a random sample of $400$ weekday commuter-rail riders in a metropolitan region. Based on the sample, the authority estimated that $64\%$ of all weekday commuter-rail riders in the region use mobile ticketing, with an associated margin of error of $4.5\%$ at the $95\%$ confidence level.', 'Which of the following is the most appropriate conclusion from the survey?', '[{"id": "A", "text": "It is plausible that the actual percentage of all weekday commuter-rail riders in the region who use mobile ticketing is between $59.5\\%$ and $68.5\\%$."}, {"id": "B", "text": "If the transit authority surveyed another $400$ riders, the new sample proportion would be guaranteed to equal $64\\%$."}, {"id": "C", "text": "Among the $400$ sampled riders, between $59.5\\%$ and $68.5\\%$ stated that they were $95\\%$ satisfied with mobile ticketing."}, {"id": "D", "text": "Exactly $64\\%$ of all transit riders across every mode of transportation in the region use mobile ticketing."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-GEO-001', 'HDSAT-M-GEO-001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Geometry and Trigonometry', 'Area and volume', 'Easy', 'spr', 'A right circular cylinder has a base radius of $4$ centimeters and a height of $9$ centimeters. The volume of the cylinder can be written in the form $k\pi$ cubic centimeters, where $k$ is a constant.', 'What is the value of $k$?', NULL, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-GEO-002', 'HDSAT-M-GEO-002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Geometry and Trigonometry', 'Right triangles and trigonometry', 'Medium', 'multiple_choice', 'In right triangle $ABC$, angle $C$ is a right angle, the length of side $AC$ is $12$, and the length of hypotenuse $AB$ is $15$.', 'What is the value of $\sin A$?', '[{"id": "A", "text": "$\\dfrac{4}{5}$"}, {"id": "B", "text": "$\\dfrac{3}{4}$"}, {"id": "C", "text": "$\\dfrac{3}{5}$"}, {"id": "D", "text": "$\\dfrac{4}{3}$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-GEO-003', 'HDSAT-M-GEO-003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Math', 'Geometry and Trigonometry', 'Circles', 'Hard', 'multiple_choice', '$$x^2 + y^2 - 6x + 8y - 11 = 0$$', 'The equation above represents a circle in the $xy$-plane. What is the radius of the circle?', '[{"id": "A", "text": "$\\sqrt{11}$"}, {"id": "B", "text": "$36$"}, {"id": "C", "text": "$6$"}, {"id": "D", "text": "$5$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-GEO-004', 'HDSAT-M-GEO-004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10']::TEXT[], 'Math', 'Geometry and Trigonometry', 'Circles', 'Hard', 'spr', 'A circle in the $xy$-plane has radius $10$. Sector $AOB$ of the circle has a central angle of $\dfrac{2\pi}{5}$ radians. The area of sector $AOB$ can be written as $m\pi$, where $m$ is a constant.', 'What is the value of $m$?', NULL, NULL, 'hdsat-benchmark-sim-1', 'HDSAT Benchmark Simulation Set A (Released Practice Form)', 'CC-BY-4.0', 'HDSAT Benchmark Simulation Set A (Released Practice Form) (CC-BY-4.0)', TRUE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-INF-001', 'A', ARRAY['A']::TEXT[], 'Choice A accurately captures the central claim: warming temperatures enable tropical herbivorous fish to move into temperate kelp habitats, where their grazing outpaces kelp regrowth and converts dense canopies into sparse reefs. Choices C and D, and D introduce claims unsupported by the passage.', '{"C": "The text never compares the growth rate of temperate kelp forests with that of tropical coral reefs.", "D": "The text contrasts native temperate species with tropical browsers rather than stating native fish changed their diets.", "B": "Rocky reefs are described as the result of kelp loss, not as a pre-existing habitat more severely warmed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-INF-002', 'A', ARRAY['A']::TEXT[], 'The passage contrasts vellum (prized for decorative illumination) with sheepskin (used for administrative registries and prone to splitting if someone tried to scrape off ink). Thus, for administrative records where preventing tampering mattered more than gold leaf, sheepskin was advantageous.', '{"C": "The passage notes registries were not intended for liturgical display, not that pigments were unavailable.", "D": "Durability over centuries is not compared in the passage.", "B": "Multispectral imaging was successfully used to identify the parchment type."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-INF-003', 'A', ARRAY['A']::TEXT[], 'To support the claim that the pairing captures nearly the full weed-suppression benefit of the cereal grass without sacrificing the legume''s nitrogen retention, Choice A directly cites the 50/50 mix''s metrics (86% and 64 kg/ha) alongside the single-crop benchmarks (89% and 68 kg/ha).', '{"D": "Mentions only the single-crop extremes without citing the paired mixture.", "B": "Focuses on Tillage Radish, which is neither the legume nor the cereal grass in the conclusion.", "C": "Cites only Crimson Clover''s nitrogen retention."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-INF-004', 'D', ARRAY['D']::TEXT[], 'Choice D directly shows railway scheduling (''six-minute intervals of the junction bell'') reshaping a character''s intimate emotional and familial perception (''measuring his father''s pauses... as though affection itself were a connection to be missed'').', '{"B": "Describes physical infrastructure and engineering rather than internal perception.", "A": "Provides literal background detail of passengers checking a timetable.", "C": "Describes mechanical logistics of steam locomotives."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-INF-005', 'D', ARRAY['D']::TEXT[], 'The text explicitly states that the panels are grown by binding agricultural byproducts with the root-like fungal network and then heat-cured.', '{"A": "Limestone calcination and fiberglass tiles are mentioned as contrasting traditional materials.", "C": "Synthetic polymers are never mentioned.", "B": "Calcination is mentioned as releasing CO2 in traditional concrete."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-INF-006', 'D', ARRAY['D']::TEXT[], 'Because changes in the geographic moisture source can alter $\delta^{18}\text{O}$ by up to 3 per mil without any change in local rainfall volume, attributing lower $\delta^{18}\text{O}$ solely to local rainfall volume can be misleading unless source-pathway changes are considered.', '{"B": "Stalagmite growth rate is not discussed.", "A": "Contradicts the text, which explains two different factors that change $\\delta^{18}\\text{O}$.", "C": "Radiometric dating of caves is not the subject of the passage."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-CRF-001', 'B', ARRAY['B']::TEXT[], '''Resilient'' means able to withstand shock or rough conditions, which contrasts directly with ''delicate'' pendulums and matches ''functioning reliably even when dropped from reconnaissance aircraft''.', '{"C": "''Ambiguous'' means open to multiple interpretations.", "D": "''Ephemeral'' means short-lived.", "A": "''Tentative'' means hesitant or provisional."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-CRF-002', 'C', ARRAY['C']::TEXT[], '''Nonhierarchical'' describes an arrangement without fixed rank or forced sequence, matching Bo Bardi''s rejection of isolating walls and her support for visitors moving freely among transparent easels.', '{"B": "''Clandestine'' means secretive.", "D": "''Redundant'' means repetitive or unnecessary.", "A": "''Perfunctory'' means carried out with minimal effort."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-CRF-003', 'D', ARRAY['D']::TEXT[], '''Univocal'' (or unqualified/unambiguous) fits the contrast: Patel does not give a single-sided endorsement, because she highlights both a benefit (faster processing) and a systemic flaw (amplifying data gaps).', '{"A": "''Mendacious'' means untruthful.", "B": "''Parsimonious'' means stingy or sparing.", "C": "''Derivative'' means unoriginal."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-CRF-004', 'C', ARRAY['C']::TEXT[], 'The first sentence states a popular simplified narrative (crediting a single dog, Balto), and the second sentence introduces historians'' broader evidence (20 mushers, 150 dogs, and Togo''s longest hazardous leg) that complicates that simplified view.', '{"A": "No future public health policy is proposed.", "B": "The passage is historical, not a comparison of competing scientific theories.", "D": "The passage corrects a narrow popular focus rather than claiming the event was ignored."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-CRF-005', 'D', ARRAY['D']::TEXT[], 'Rostova shows that paved urban heat islands are harsher than surrounding deserts, causing some native trees to die back while hardy non-native trees provide shade that cools sidewalks and helps native understory shrubs survive.', '{"A": "Rostova does not address or dispute songbird diet.", "B": "Artificial shade structures are never mentioned.", "C": "Rostova highlights the benefits of Mediterranean oaks in Phoenix boulevards."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-SEC-001', 'B', ARRAY['B']::TEXT[], 'The text contains two independent clauses: ''In 1899, physicist Hertha Ayrton read her paper... in London'' and ''shortly thereafter, she became the first woman...''. A semicolon properly joins the two independent clauses, followed by a comma after the introductory transition phrase ''shortly thereafter''.', '{"C": "Creates a comma splice between two independent clauses.", "D": "Creates a fused (run-on) sentence with no punctuation between independent clauses.", "A": "Creates a comma splice."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-SEC-002', 'A', ARRAY['A']::TEXT[], 'The plural subject ''The acoustics'' requires a plural verb, and the temporal phrase ''for decades'' calls for the present perfect tense (''have intrigued''). Choices C and D, and D are all singular verbs.', '{"C": "Singular verb ''has'' does not agree with plural subject ''acoustics''.", "D": "Singular verb ''is'' does not agree with ''acoustics'' or fit ''for decades''.", "B": "Singular verb ''intrigues'' does not agree with ''acoustics''."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-SEC-003', 'D', ARRAY['D']::TEXT[], 'The introductory participial phrase ''Calibrated using laser interferometry in an underground vacuum chamber'' must modify the noun immediately following the comma. ''The suspended silica mirrors of the LIGO observatory'' are what are calibrated and can detect the strain amplitudes.', '{"A": "Creates a dangling modifier: strain amplitudes are not calibrated in a vacuum chamber.", "B": "Measurements are not physical objects calibrated in an underground vacuum chamber that themselves detect strain.", "C": "Expletive ''it'' cannot be modified by ''Calibrated using laser interferometry''."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-SEC-004', 'C', ARRAY['C']::TEXT[], 'Within the ''that'' clause, ''when sweetgrass (Hierochloe odorata) is harvested selectively by hand'' is a dependent adverbial clause preceding the main clause ''the plant responds...''. A comma is required after ''hand'' to separate the dependent clause from the independent clause.', '{"B": "A semicolon cannot separate a dependent ''when'' clause from its main clause.", "A": "Omits the necessary comma after an introductory dependent clause.", "D": "An em dash is inappropriate when no paired dash or abrupt break exists."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-EXP-001', 'A', ARRAY['A']::TEXT[], 'The second sentence overturns the assumption described in the first sentence (''hydrologically isolated... stagnant'' vs. ''periodically flushes through interconnected channels''). ''However,'' signals this contrast.', '{"C": "''Consequently,'' indicates cause and effect.", "B": "''Similarly,'' indicates comparison of alike ideas.", "D": "''For instance,'' introduces an example of the preceding claim rather than a refutation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-EXP-002', 'C', ARRAY['C']::TEXT[], 'Choice C synthesizes all parts of the prompt: acknowledging the lower energy density, explaining why weight is unimportant for stationary storage, and highlighting both cold-weather retention (>88% at -20°C) and abundant sodium materials.', '{"B": "Omits cold-weather performance and stationary grid storage altogether.", "A": "Juxtaposes statistics without explaining why stationary grid storage favors sodium-ion.", "D": "Fails to mention energy density, cold-weather performance, or material cost."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-EXP-003', 'C', ARRAY['C']::TEXT[], 'Choice C explicitly states the engineering trade-off: halving the speed from 33 1/3 rpm to 16 2/3 rpm doubled the audio capacity while sacrificing some high-frequency fidelity.', '{"D": "Provides general background without mentioning the engineering trade-off.", "A": "States the speed difference without explaining the benefit or cost.", "B": "Describes the contents without mentioning any trade-off."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALG-001', 'B', ARRAY['B', '19']::TEXT[], 'Substitute $W = 195$ into the linear equation: $195 = 480 - 15t$. Subtract $195$ from $480$: $15t = 285$. Divide both sides by $15$: $t = 285 / 15 = 19$ hours.', '{"C": "Result of arithmetic error $255 / 15 = 17$.", "D": "Result of $315 / 15 = 21$.", "A": "Total time to empty the entire $480$-liter tank ($480 / 15 = 32$)."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALG-002', '9', ARRAY['9', '9.0']::TEXT[], 'Multiply the second equation by $2$ to eliminate $y$: $10x - 4y = 34$. Adding this to the first equation gives $13x = 65$, so $x = 5$. Substituting $x = 5$ into $3x + 4y = 31$ gives $15 + 4y = 31$, so $y = 4$. Therefore $x + y = 5 + 4 = 9$.', '{}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALG-003', 'C', ARRAY['C']::TEXT[], 'In the linear model $C(m) = 18 + 0.15m$, the constant term $18$ is the $y$-intercept $C(0)$, representing the fixed monthly membership fee before any overage minutes are incurred.', '{"B": "The per-minute overage rate is $0.15$, the slope of the linear function.", "D": "The variable $m$ counts overage minutes; $18$ is measured in dollars.", "A": "The function models monthly cost for $m$ overage minutes, not the cost of an $18$-minute trip."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALG-004', 'B', ARRAY['B', '45']::TEXT[], 'The flour constraint is $0.6s + 0.4b \le 36$ with $s \ge 30$. To maximize $b$, use the minimum required sourdough loaves $s = 30$: $0.6(30) + 0.4b \le 36 \Rightarrow 18 + 0.4b \le 36 \Rightarrow 0.4b \le 18 \Rightarrow b \le 45$.', '{"C": "This is the minimum number of sourdough loaves required, not the maximum number of brioche batches.", "D": "Divides $36$ by $0.6$ instead of accounting for the sourdough requirement.", "A": "Assumes $s = 0$, ignoring the constraint $s \\ge 30$."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALG-005', '5', ARRAY['5', '5.0']::TEXT[], 'A system of two linear equations has infinitely many solutions when one equation is a non-zero constant multiple of the other. Comparing the $y$-coefficients and constant terms, $-18 = 3(-6)$ and $42 = 3(14)$. Therefore the second equation is $3$ times the first equation, so $15 = 3k$, which gives $k = 5$.', '{}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ADV-001', 'C', ARRAY['C']::TEXT[], 'Distribute the subtraction sign across the second polynomial: $2x^2 - 5x + 3 - x^2 + 4x + 7$. Combine like terms: $(2x^2 - x^2) + (-5x + 4x) + (3 + 7) = x^2 - x + 10$.', '{"A": "Fails to distribute the negative sign to $-4x$ and $-7$.", "B": "Distributes the negative sign to $-4x$ but not to $-7$.", "D": "Adds the $x^2$ terms instead of subtracting."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ADV-002', 'B', ARRAY['B', '92']::TEXT[], 'For a quadratic function $h(t) = at^2 + bt + c$ with $a < 0$, the maximum occurs at the vertex $t = -b/(2a) = -40 / (2 \cdot (-5)) = 4$ seconds. Evaluating $h(4) = -5(4)^2 + 40(4) + 12 = -80 + 160 + 12 = 92$ meters.', '{"D": "Omits the initial platform height of $12$ meters.", "A": "Evaluates $h(2)$ instead of the vertex $h(4)$.", "C": "Gives the time $t = 4$ seconds at which the maximum occurs rather than the maximum height."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ADV-003', '5', ARRAY['5', '5.0']::TEXT[], 'Factor the quadratic expression: $(x - 3)(x - 8) = 0$. The solutions are $x = 8$ and $x = 3$. The positive difference between the two solutions is $8 - 3 = 5$.', '{}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ADV-004', 'B', ARRAY['B']::TEXT[], 'Because the population doubles every $3$ hours, the growth factor per $3$-hour period is $2$, and the number of $3$-hour doubling periods in $t$ hours is $t/3$. Thus $P(t) = 2{,}500(2)^{t/3}$.', '{"D": "Models a population that doubles $3$ times per hour (every $20$ minutes).", "A": "Uses base $3$ (tripling) instead of base $2$ (doubling).", "C": "Adds the exponential term instead of multiplying the initial population."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ADV-005', '18', ARRAY['18', '18.0']::TEXT[], 'A quadratic equation $ax^2 + bx + c = 0$ has exactly one real solution when its discriminant $b^2 - 4ac$ equals $0$. Here $a = 2$ and $b = -12$, so $(-12)^2 - 4(2)(c) = 0 \Rightarrow 144 - 8c = 0 \Rightarrow c = 18$.', '{}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-PSD-001', 'A', ARRAY['A', '468']::TEXT[], 'After the $20\%$ reduction, the sale price is $650 \times 0.80 = \$520$. Taking an additional $10\%$ off the sale price yields $520 \times 0.90 = \$468$.', '{"D": "Adds the two percentages ($30\\%$) and computes $650 \\times 0.70 = 455$.", "B": "Applies only the initial $20\\%$ discount.", "C": "Applies only a $10\\%$ discount."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-PSD-002', '11', ARRAY['11', '11.0']::TEXT[], 'The ordered $7$-day dataset is $14, 18, 21, 21, 25, 33, 92$. The median (fourth value) is $21$. The sum of all $7$ readings is $14 + 18 + 21 + 21 + 25 + 33 + 92 = 224$, so the mean is $224 / 7 = 32$. The mean exceeds the median by $32 - 21 = 11$.', '{}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-PSD-003', 'B', ARRAY['B']::TEXT[], 'The condition restricts the sample space to the $225$ panels that passed inspection. Of those, $132$ came from Line A. The conditional probability is $132 / 225 = 44 / 75$ (dividing numerator and denominator by $3$).', '{"D": "Computes $132 / 140$, the probability that a Line A panel passed.", "C": "Computes $132 / 240$, the unconditional proportion of all panels that came from Line A and passed.", "A": "Computes $140 / 240$, the proportion of all panels produced on Line A."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-PSD-004', 'A', ARRAY['A']::TEXT[], 'A sample estimate of $64\%$ with a margin of error of $\pm 4.5\%$ yields a plausible interval of $64\% - 4.5\% = 59.5\%$ to $64\% + 4.5\% = 68.5\%$ for the population from which the random sample was drawn (weekday commuter-rail riders in the region).', '{"D": "Overgeneralizes beyond commuter-rail riders and treats the sample estimate as an exact population value.", "C": "Confuses the confidence level and margin of error with individual rider satisfaction.", "B": "New random samples vary due to sampling variability; they are not guaranteed to match $64\\%$."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-GEO-001', '144', ARRAY['144', '144.0']::TEXT[], 'The volume of a right circular cylinder is $V = \pi r^2 h$. Substituting $r = 4$ and $h = 9$ gives $V = \pi (4)^2 (9) = 144\pi$ cubic centimeters, so $k = 144$.', '{}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-GEO-002', 'C', ARRAY['C']::TEXT[], 'By the Pythagorean theorem, $BC = \sqrt{15^2 - 12^2} = \sqrt{225 - 144} = \sqrt{81} = 9$. Side $BC$ is opposite angle $A$, so $\sin A = \text{opposite}/\text{hypotenuse} = 9 / 15 = 3 / 5$.', '{"A": "Equals $\\cos A = 12/15 = 4/5$.", "B": "Equals $\\tan A = 9/12 = 3/4$.", "D": "Equals $\\cot A = 12/9 = 4/3$, which is greater than $1$."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-GEO-003', 'C', ARRAY['C', '6']::TEXT[], 'Complete the square for $x$ and $y$: $(x^2 - 6x + 9) + (y^2 + 8y + 16) = 11 + 9 + 16 \Rightarrow (x - 3)^2 + (y + 4)^2 = 36$. In standard form $(x - h)^2 + (y - k)^2 = r^2$, we have $r^2 = 36$, so the radius is $r = 6$.', '{"B": "Gives $r^2 = 36$ instead of $r = 6$.", "A": "Takes the square root of the constant term before completing the square.", "D": "Finds $\\sqrt{9 + 16} = 5$, omitting the $11$ on the right-hand side."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-GEO-004', '20', ARRAY['20', '20.0']::TEXT[], 'The area of a sector with central angle $\theta$ radians is $\frac{1}{2}r^2\theta$. Substituting $r = 10$ and $\theta = \frac{2\pi}{5}$ gives $\text{Area} = \frac{1}{2}(100)\left(\frac{2\pi}{5}\right) = 20\pi$. Thus $m = 20$.', '{}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
