INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-001', 'formula', 'algebra', 'Slope between two points', NULL, 'Slope equals rise over run; the denominator cannot be zero.', 'm=\dfrac{y_2-y_1}{x_2-x_1}', ARRAY['algebra']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-002', 'formula', 'algebra', 'Slope-intercept form', NULL, 'm is the slope and b is the y-intercept.', 'y=mx+b', ARRAY['algebra']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-003', 'formula', 'advanced-math', 'Quadratic formula', NULL, 'Solves ax^2+bx+c=0. The expression under the radical is the discriminant.', 'x=\dfrac{-b\pm\sqrt{b^2-4ac}}{2a}', ARRAY['advanced-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-004', 'formula', 'advanced-math', 'Vertex of a parabola', NULL, 'The x-coordinate of the vertex of y = ax^2 + bx + c (also the axis of symmetry).', 'x=-\dfrac{b}{2a}', ARRAY['advanced-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-005', 'formula', 'advanced-math', 'Difference of squares', NULL, 'Factors any difference of two perfect squares.', 'a^2-b^2=(a+b)(a-b)', ARRAY['advanced-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-006', 'formula', 'advanced-math', 'Perfect square trinomials', NULL, 'Recognise these to factor quickly without expanding.', 'a^2\pm2ab+b^2=(a\pm b)^2', ARRAY['advanced-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-007', 'formula', 'advanced-math', 'Exponent rules', NULL, 'Add exponents when multiplying like bases, subtract when dividing, multiply when raising a power to a power.', 'x^a x^b = x^{a+b}, \quad \dfrac{x^a}{x^b}=x^{a-b}, \quad (x^a)^b=x^{ab}', ARRAY['advanced-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-008', 'formula', 'problem-solving', 'Percent change', NULL, 'A positive result is an increase; a negative result is a decrease.', '\%\Delta=\dfrac{\text{new}-\text{old}}{\text{old}}\times100', ARRAY['problem-solving']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-009', 'formula', 'problem-solving', 'Exponential growth and decay', NULL, 'a is the initial amount, r the rate per period, t the number of periods.', 'y=a(1\pm r)^t', ARRAY['problem-solving']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-010', 'formula', 'problem-solving', 'Compound interest', NULL, 'P principal, r annual rate, n compounds per year, t years.', 'A=P\left(1+\dfrac{r}{n}\right)^{nt}', ARRAY['problem-solving']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-011', 'formula', 'problem-solving', 'Distance, rate, time', NULL, 'Distance equals rate multiplied by time; rearrange for the unknown.', 'd=rt', ARRAY['problem-solving']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-012', 'formula', 'problem-solving', 'Average (arithmetic mean)', NULL, 'Use sum = mean x count to find a missing value.', '\bar{x}=\dfrac{\text{sum of values}}{\text{number of values}}', ARRAY['problem-solving']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-013', 'formula', 'geometry', 'Pythagorean theorem', NULL, 'For a right triangle, c is the hypotenuse.', 'a^2+b^2=c^2', ARRAY['geometry']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-014', 'formula', 'geometry', 'Special right triangles', NULL, 'Sides are in a fixed ratio, so one known side gives the others.', '45\text{-}45\text{-}90:\; x, x, x\sqrt2 \qquad 30\text{-}60\text{-}90:\; x, x\sqrt3, 2x', ARRAY['geometry']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-015', 'formula', 'geometry', 'Circle: area and circumference', NULL, 'Area uses the square of the radius; circumference is the full distance around.', 'A=\pi r^2, \qquad C=2\pi r', ARRAY['geometry']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-016', 'formula', 'geometry', 'Circle equation (centre–radius form)', NULL, 'Centre (h, k) and radius r.', '(x-h)^2+(y-k)^2=r^2', ARRAY['geometry']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-017', 'formula', 'geometry', 'Sector and arc of a circle', NULL, 'The fraction of the circle is central angle divided by 360 degrees.', '\text{arc}=\dfrac{\theta}{360}2\pi r, \qquad \text{sector}=\dfrac{\theta}{360}\pi r^2', ARRAY['geometry']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-018', 'formula', 'geometry', 'Volume and surface area', NULL, 'The reference sheet supplies these; know which one each problem needs.', 'V_{box}=lwh,\; V_{cyl}=\pi r^2h,\; V_{sph}=\tfrac43\pi r^3,\; V_{cone}=\tfrac13\pi r^2h', ARRAY['geometry']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-019', 'formula', 'trigonometry', 'Right-triangle trigonometry', NULL, 'The reference sheet lists both degree and radian values for common angles.', '\sin\theta=\dfrac{\text{opp}}{\text{hyp}},\; \cos\theta=\dfrac{\text{adj}}{\text{hyp}},\; \tan\theta=\dfrac{\text{opp}}{\text{adj}}', ARRAY['trigonometry']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-020', 'formula', 'trigonometry', 'Sine, cosine and tangent identities', NULL, 'The Pythagorean identity lets you convert between sine and cosine.', '\sin^2\theta+\cos^2\theta=1, \quad \tan\theta=\dfrac{\sin\theta}{\cos\theta}', ARRAY['trigonometry']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-021', 'formula', 'trigonometry', 'Radians and degrees', NULL, 'Multiply by pi/180 for degrees to radians; by 180/pi for radians to degrees.', '\pi \text{ rad}=180^\circ', ARRAY['trigonometry']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-022', 'formula', 'algebra', 'Systems: substitution and elimination', NULL, 'Parallel lines give no solution; identical lines give infinitely many.', '\text{inconsistent}\Rightarrow \text{no solution}, \quad \text{dependent}\Rightarrow \text{infinitely many}', ARRAY['algebra']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
